import React, { useState, useContext } from 'react';
import { View, Text, StyleSheet, TextInput, TouchableOpacity, ScrollView } from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import { theme } from '../theme';
import { HabitContext } from '../context/HabitContext';

const FREQUENCIES = ['Daily', 'Weekdays', 'Weekends'];

// CreateHabitScreen allows inputting a new habit title and frequency
export default function CreateHabitScreen({ navigation }) {
  const [title, setTitle] = useState('');
  const [frequency, setFrequency] = useState('Daily');
  const [error, setError] = useState('');
  const { addHabit } = useContext(HabitContext);

  const handleSave = () => {
    if (!title.trim()) {
      setError('Please enter a habit title');
      return;
    }
    addHabit(title.trim(), frequency);
    navigation.goBack();
  };

  return (
    <ScrollView style={styles.container}>
      <View style={styles.header}>
        <TouchableOpacity onPress={() => navigation.goBack()} style={styles.backButton}>
          <Ionicons name="arrow-back" size={20} color={theme.colors.textPrimary} />
        </TouchableOpacity>
        <Text style={styles.title}>New Habit</Text>
      </View>

      <View style={styles.card}>
        <Text style={styles.label}>Habit Title</Text>
        <TextInput
          style={styles.input}
          placeholder="e.g. Morning Jog, Code for 1 hour"
          placeholderTextColor={theme.colors.textSecondary}
          value={title}
          onChangeText={(text) => {
            setTitle(text);
            if (error) setError('');
          }}
          autoFocus
        />
        {error ? <Text style={styles.errorText}>{error}</Text> : null}

        <Text style={styles.label}>Target Frequency</Text>
        <View style={styles.frequencyContainer}>
          {FREQUENCIES.map((freq) => {
            const isSelected = frequency === freq;
            return (
              <TouchableOpacity
                key={freq}
                style={[styles.freqChip, isSelected && styles.freqChipSelected]}
                onPress={() => setFrequency(freq)}
              >
                <Text style={[styles.freqText, isSelected && styles.freqTextSelected]}>
                  {freq}
                </Text>
              </TouchableOpacity>
            );
          })}
        </View>

        <TouchableOpacity style={styles.saveButton} onPress={handleSave}>
          <Text style={styles.saveButtonText}>Save Habit</Text>
        </TouchableOpacity>
      </View>
    </ScrollView>
  );
}

