import React, { useContext } from 'react';
import { View, Text, StyleSheet, ScrollView } from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import { theme } from '../theme';
import { HabitContext } from '../context/HabitContext';
import EmptyState from '../components/EmptyState';

// Helper to generate past 7 days array with formatted weekday labels
function getPast7Days() {
  const days = [];
  const today = new Date();
  for (let i = 6; i >= 0; i--) {
    const d = new Date(today);
    d.setDate(today.getDate() - i);
    const dateKey = d.toISOString().split('T')[0];
    const weekday = d.toLocaleDateString('en-US', { weekday: 'short' });
    days.push({ dateKey, weekday, dayNum: d.getDate() });
  }
  return days;
}

// ProgressScreen visualizes completion rates over the past 7 days in a clean grid
export default function ProgressScreen({ navigation }) {
  const { habits, loading } = useContext(HabitContext);
  const pastDays = getPast7Days();

  if (loading) {
    return (
      <View style={[styles.container, styles.centered]}>
        <Text style={styles.loadingText}>Loading progress...</Text>
      </View>
    );
  }

  return (
    <ScrollView style={styles.container} contentContainerStyle={styles.scrollContent}>
      <Text style={styles.subtitle}>ANALYTICS</Text>
      <Text style={styles.title}>Weekly Progress</Text>

      {habits.length === 0 ? (
        <EmptyState
          icon="stats-chart-outline"
          title="No progress data"
          message="Create and track habits to visualize your 7-day consistency grid."
          ctaLabel="Go to Today"
          onCta={() => navigation.navigate('Today')}
        />
      ) : (
        habits.map((habit) => {
          return (
            <View key={habit.id} style={styles.habitCard}>
              <View style={styles.habitHeader}>
                <Text style={styles.habitTitle}>{habit.title}</Text>
                <View style={styles.streakInfo}>
                  <Ionicons name="flame" size={14} color={theme.colors.success} />
                  <Text style={styles.streakNumber}>{habit.streak} day streak</Text>
                </View>
