import React, { createContext, useState, useEffect } from 'react';
import AsyncStorage from '@react-native-async-storage/async-storage';

const STORAGE_KEY = '@habit_pulse_habits_v1';

// Helper to calculate streak based on history record and target frequency
export function calculateStreak(history = {}) {
  let streak = 0;
  const today = new Date();

  // Iterate backwards from today to count consecutive completions
  for (let i = 0; i < 30; i++) {
    const d = new Date(today);
    d.setDate(today.getDate() - i);
    const dateKey = d.toISOString().split('T')[0];

    if (history[dateKey]) {
      streak++;
    } else if (i === 0) {
      // If today is not checked in yet, don't break the streak immediately; check yesterday
      continue;
    } else {
      break;
    }
  }
  return streak;
}

// Generate default seed history for past 3 days so cards look active
const getInitialHistory = () => {
  const history = {};
  const today = new Date();
  for (let i = 1; i <= 3; i++) {
    const d = new Date(today);
    d.setDate(today.getDate() - i);
    history[d.toISOString().split('T')[0]] = true;
  }
  return history;
};

const INITIAL_HABITS = [
  {
    id: '1',
    title: 'Morning Hydration 💧',
    targetFrequency: 'Daily',
    streak: 3,
    history: getInitialHistory(),
    createdAt: new Date().toISOString(),
  },
  {
    id: '2',
    title: 'Read 20 Pages 📖',
    targetFrequency: 'Daily',
    streak: 3,
    history: getInitialHistory(),
    createdAt: new Date().toISOString(),
  },
];

export const HabitContext = createContext();

export function HabitProvider({ children }) {
  const [habits, setHabits] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    async function loadStoredHabits() {
      try {
        const stored = await AsyncStorage.getItem(STORAGE_KEY);
        if (stored) {
          const parsed = JSON.parse(stored);
          // Recalculate streaks on load in case days passed
          const updated = parsed.map((h) => ({
            ...h,
            streak: calculateStreak(h.history),
          }));
          setHabits(updated);
        } else {
          setHabits(INITIAL_HABITS);
          await AsyncStorage.setItem(STORAGE_KEY, JSON.stringify(INITIAL_HABITS));
        }
      } catch (e) {
        console.error('Failed to load habits from storage', e);
      } finally {
        setLoading(false);
      }
    }
    loadStoredHabits();
  }, []);

  const saveHabits = async (newHabits) => {
    try {
      setHabits(newHabits);
      await AsyncStorage.setItem(STORAGE_KEY, JSON.stringify(newHabits));
    } catch (e) {
      console.error('Failed to save habits to storage', e);
    }
  };

  const addHabit = (title, targetFrequency) => {
    const newHabit = {
      id: Date.now().toString(),
      title,
      targetFrequency,
      streak: 0,
      history: {},
      createdAt: new Date().toISOString(),
    };
    saveHabits([newHabit, ...habits]);
  };

  const deleteHabit = (id) => {
    const filtered = habits.filter((h) => h.id !== id);
    saveHabits(filtered);
  };

  // Toggle check-in status for today and recompute streaks
  const toggleCheckIn = (id) => {
    const todayKey = new Date().toISOString().split('T')[0];
    const updated = habits.map((habit) => {
      if (habit.id === id) {
        const newHistory = { ...habit.history };
        if (newHistory[todayKey]) {
          delete newHistory[todayKey];
        } else {
          newHistory[todayKey] = true;
        }
        const newStreak = calculateStreak(newHistory);
        return { ...habit, history: newHistory, streak: newStreak };
      }
      return habit;
    });
    saveHabits(updated);
  };

  return (
    <HabitContext.Provider value={{ habits, loading, addHabit, deleteHabit, toggleCheckIn }}>
      {children}
    </HabitContext.Provider>
  );
}

